css:
/* Recibo de Vencimentos - Angola
   Matches the PRIMAVERA BSS receipt this replaces: no background fills, no boxes, no
   rounded corners — hairline rules and whitespace do the separating.
   Targets wkhtmltopdf (Qt WebKit): table-based, sized in pt, no flexbox or grid. */

.recibo {
  font-family: "DejaVu Sans", Arial, Helvetica, sans-serif;
  font-size: 7.2pt;
  line-height: 1.45;
  color: #000;
  width: 100%;
}
.recibo table { border-collapse: collapse; width: 100%; }
.recibo td, .recibo th { vertical-align: top; }
.recibo .n { text-align: right; white-space: nowrap; }

/* ---- overrides for Frappe's print stylesheet ----
   print.css ships three rules that fight this layout and all carry !important:
     .print-format td, .print-format th { padding: 6px !important }
     .print-format th { background-color: #eee !important }
     .print-format th { border-bottom: 0px !important }
   The receipt is fill-free by design and far more compact than 6px cells allow, so they
   are countered here at the same weight. Scoped to .recibo — no other format is touched.
   Every padding rule below is likewise marked !important for the same reason. */
.recibo th { background-color: transparent !important; }
.recibo .mini .hd th { border-bottom: .7pt solid #000 !important; }
.recibo .lines th { border-bottom: .7pt solid #000 !important; }

/* ---- header ---- */
.recibo .hdr { margin-bottom: 10pt; }
.recibo .hdr td { font-size: 7.2pt; }
.recibo .hdr-a { width: 40%; }
.recibo .hdr-b { width: 38%; }
.recibo .hdr-c { width: 22%; }
.recibo .co-name { font-weight: bold; font-size: 8pt; }

/* ---- "Original" / "Duplicado" ---- */
.recibo .copy { font-size: 7pt; margin-bottom: 10pt; }

/* ---- title ---- */
.recibo .title { font-size: 13pt; font-weight: bold; letter-spacing: .2pt; }
.recibo .rule-title { border-bottom: 1pt solid #000; margin: 5pt 0 7pt 0; }

.recibo .stamp {
  border: .8pt solid #000; padding: 2pt 4pt !important; margin-bottom: 6pt;
  font-weight: bold; font-size: 8pt; text-align: center; letter-spacing: 1pt;
}

/* ---- period / employee block: labels and values only, no rules, no fills ---- */
.recibo .kv { margin-bottom: 11pt; }
.recibo .kv td { padding: 1.4pt 0 !important; }
.recibo .kv .k  { width: 11%; white-space: nowrap; }
.recibo .kv .v  { width: 22%; padding-right: 22pt !important; }
.recibo .kv .k2 { width: 15%; white-space: nowrap; padding-right: 10pt !important; }
.recibo .kv .v2 { width: 50%; }

/* ---- section captions ---- */
.recibo .sec { font-weight: bold; font-size: 7.2pt; margin-bottom: 2pt; }

/* ---- small tables: a rule under the heading row, nothing else ---- */
.recibo .mini th {
  font-weight: normal; text-align: left; padding: 1pt 4pt 2pt 0 !important; white-space: nowrap;
}
.recibo .mini .hd th { border-bottom: .7pt solid #000; }
.recibo .mini td { padding: 2pt 4pt 2pt 0 !important; }

.recibo .split { margin-bottom: 12pt; }
.recibo .split-l { width: 60%; padding-right: 24pt !important; }
.recibo .split-r { width: 40%; }
.recibo .irt th, .recibo .irt td { text-align: right; padding-right: 0 !important; }
.recibo .irt th:first-child, .recibo .irt td:first-child { padding-right: 24pt !important; }

/* ---- main lines table ---- */
.recibo .lines { margin-bottom: 10pt; }
.recibo .lines th {
  font-weight: bold; text-align: left; padding: 2pt 4pt 2.5pt 0 !important;
  border-top: .7pt solid #000; border-bottom: .7pt solid #000; white-space: nowrap;
}
.recibo .lines td { padding: 2.2pt 4pt 2.2pt 0 !important; border-bottom: .5pt solid #cfcfcf; }
.recibo .lines .c-cod { width: 8%; }
.recibo .lines .c-dat { width: 11%; white-space: nowrap; }
.recibo .lines .c-des { width: 45%; }
.recibo .lines .c-val { width: 18%; text-align: right; padding-right: 0 !important; }
.recibo .lines th.c-val { text-align: right; }
.recibo .lines .memo td { color: #333; }
.recibo .lines .pad td { height: 10.5pt; border-bottom: 0; }
.recibo .lines tfoot .tot td {
  border-top: .7pt solid #000; border-bottom: 0; font-weight: bold; padding-top: 3pt !important;
}
.recibo .lines tfoot .tot-l { text-align: right; padding-right: 14pt !important; }

/* ---- overtime ---- */
.recibo .ot { margin-bottom: 10pt; }
.recibo .ot .ot-tot td { font-weight: bold; border-bottom: 0; border-top: .5pt solid #000; }

.recibo .warn {
  border: .8pt solid #000; padding: 3pt 5pt !important; margin-bottom: 8pt;
  font-weight: bold; font-size: 7pt;
}

/* ---- payment methods + total pago, side by side ---- */
.recibo .paywrap { margin-bottom: 18pt; }
.recibo .paywrap-l { width: 64%; padding-right: 14pt !important; }
.recibo .paywrap-r { width: 36%; vertical-align: bottom; }
.recibo .pay .c-pct { width: 11%; text-align: right; padding-right: 10pt !important; }
.recibo .pay th.c-pct { text-align: right; padding-right: 10pt !important; }
.recibo .pay .c-rem { width: 26%; text-align: right; padding-right: 10pt !important; }
.recibo .pay th.c-rem { text-align: right; padding-right: 10pt !important; }
.recibo .pay .c-moe { width: 12%; }
.recibo .pago td { padding: 2pt 0 !important; font-weight: bold; font-size: 8.5pt; }
.recibo .pago .pago-l { text-align: right; padding-right: 18pt !important; white-space: nowrap; }
.recibo .pago .pago-v { text-align: right; }

/* ---- declaration + signature ---- */
.recibo .foot .decl { width: 52%; font-style: italic; }
.recibo .foot .obs { width: 48%; font-weight: bold; }
.recibo .foot .sig { padding-top: 20pt !important; }
.recibo .foot .sig-line { border-bottom: .7pt solid #000; width: 62%; height: 1pt; }

/* ---- print behaviour ---- */
@media print {
  .recibo { font-size: 7.2pt; }
  .recibo table, .recibo tr, .recibo .foot, .recibo .paywrap { page-break-inside: avoid; }
  .recibo thead { display: table-header-group; }
}
